        var statusStrip = new StatusStrip();
        // .NET 9 behavioral change: StatusStrip default renderer changed.
        // Explicitly set RenderMode to preserve .NET 8 appearance.
        statusStrip.RenderMode = ToolStripRenderMode.System;
        form.Controls.Add(statusStrip);

        Application.Run(form);
    }
}

/// <summary>
/// Example editor that uses IWindowsFormsEditorService.
/// In .NET 9, DropDownControl parameter is now non-nullable.
/// Guard against passing null.
/// </summary>
class MyEditor : UITypeEditor
{
    public override object? EditValue(ITypeDescriptorContext? context, IServiceProvider provider, object? value)
    {
        var editorService = provider?.GetService(typeof(IWindowsFormsEditorService)) as IWindowsFormsEditorService;
        if (editorService != null)
        {
            var control = CreateEditorControl(value);
            // .NET 9 breaking change: DropDownControl parameter is now non-nullable.
            // Only call if control is not null.
            if (control != null)
            {
                editorService.DropDownControl(control);
            }
        }
        return value;
    }

    private Control? CreateEditorControl(object? value)
    {
        // May return null in some cases
        if (value == null) return null;
        return new ListBox();
    }
}

